"""Lexer and recursive-descent parser for minisql. See SPEC.md, "Syntax".

``parse(sql)`` turns a query string into a :class:`minisql.ast.Query`, or
raises :class:`minisql.errors.QueryError` describing the first syntax error.

Decisions not pinned down by the spec:

* Comparisons don't chain: ``a = b = c`` and ``a < b IS NULL`` are syntax
  errors (use parentheses). Their operands are parsed at the additive level,
  so the ``AND`` in ``x BETWEEN 1 AND 2 AND y`` belongs to ``BETWEEN``.
* ``NOT`` is a prefix operator binding looser than comparisons, so
  ``NOT a = b`` is ``NOT (a = b)``; it can repeat (``NOT NOT x``). It can't
  appear directly as a comparison operand (``a = NOT b`` is an error).
* Unary ``-`` can repeat (``--1`` is ``-(-(1))``); there are no comments.
* A function call is an *unquoted* name directly followed by ``(``.
  ``name()`` gives ``Call(NAME, [])``; ``name(*)`` gives ``star=True``.
  Names and arity are left to the executor.
* Unquoted names are ASCII: ``[A-Za-z_][A-Za-z0-9_]*``. Numbers are ASCII
  digits; a number immediately followed by a letter, digit, ``_`` or ``.``
  (``1abc``, ``1.2.3``) is an error.
* ``LIMIT`` and ``OFFSET`` take a non-negative integer literal only.
"""

from typing import List, NamedTuple, Optional

from . import ast
from .errors import QueryError

__all__ = ["parse", "KEYWORDS"]

KEYWORDS = frozenset(
    """
    SELECT DISTINCT FROM WHERE GROUP BY HAVING ORDER ASC DESC LIMIT OFFSET
    AS AND OR NOT IS NULL IN BETWEEN LIKE TRUE FALSE
    """.split()
)

# Token kinds
KEYWORD = "keyword"  # value: upper-cased keyword
NAME = "name"  # value: name as written
QNAME = "quoted name"  # value: unescaped name
INT = "integer"
FLOAT = "decimal"
STRING = "string"
OP = "operator"  # value: the operator / punctuation text
EOF = "end of query"

_OPERATORS = ("<=", ">=", "<>", "!=", "||", "=", "<", ">", "+", "-", "*", "/", "(", ")", ",", ";")
_WHITESPACE = " \t\n\r\f\v"
_DIGITS = "0123456789"
_NAME_START = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_"
_NAME_CHARS = _NAME_START + _DIGITS


class Token(NamedTuple):
    kind: str
    value: object
    start: int  # offset of the first character in the source
    end: int  # offset just past the last character


def _where(sql: str, pos: int) -> str:
    line = sql.count("\n", 0, pos) + 1
    col = pos - (sql.rfind("\n", 0, pos) + 1) + 1
    return "line %d, column %d" % (line, col)


def _error(sql: str, pos: int, message: str) -> QueryError:
    return QueryError("syntax error at %s: %s" % (_where(sql, pos), message))


def tokenize(sql: str) -> List[Token]:
    """Split ``sql`` into tokens, ending with an EOF token."""
    tokens = []
    i = 0
    n = len(sql)
    while i < n:
        c = sql[i]
        if c in _WHITESPACE:
            i += 1
            continue
        start = i
        if c in _NAME_START:
            while i < n and sql[i] in _NAME_CHARS:
                i += 1
            word = sql[start:i]
            if word.upper() in KEYWORDS:
                tokens.append(Token(KEYWORD, word.upper(), start, i))
            else:
                tokens.append(Token(NAME, word, start, i))
        elif c in _DIGITS or (c == "." and i + 1 < n and sql[i + 1] in _DIGITS):
            while i < n and sql[i] in _DIGITS:
                i += 1
            is_float = False
            if i < n and sql[i] == ".":
                is_float = True
                i += 1
                while i < n and sql[i] in _DIGITS:
                    i += 1
            if i < n and (sql[i] in _NAME_CHARS or sql[i] == "."):
                raise _error(sql, start, "malformed number %r" % sql[start : i + 1])
            text = sql[start:i]
            if is_float:
                tokens.append(Token(FLOAT, float(text), start, i))
            else:
                tokens.append(Token(INT, int(text), start, i))
        elif c == "'" or c == '"':
            quote = c
            parts = []
            i += 1
            while True:
                j = sql.find(quote, i)
                if j < 0:
                    what = "string" if quote == "'" else "quoted name"
                    raise _error(sql, start, "unterminated %s" % what)
                parts.append(sql[i:j])
                if j + 1 < n and sql[j + 1] == quote:
                    parts.append(quote)
                    i = j + 2
                else:
                    i = j + 1
                    break
            value = "".join(parts)
            if quote == "'":
                tokens.append(Token(STRING, value, start, i))
            else:
                if value == "":
                    raise _error(sql, start, "empty quoted name")
                tokens.append(Token(QNAME, value, start, i))
        else:
            for op in _OPERATORS:
                if sql.startswith(op, i):
                    i += len(op)
                    tokens.append(Token(OP, op, start, i))
                    break
            else:
                raise _error(sql, start, "unexpected character %r" % c)
    tokens.append(Token(EOF, None, n, n))
    return tokens


def _describe(tok: Token) -> str:
    if tok.kind == EOF:
        return "end of query"
    if tok.kind == KEYWORD:
        return "keyword %s" % tok.value
    if tok.kind == OP:
        return "'%s'" % tok.value
    return "%s %r" % (tok.kind, tok.value)


class _Parser:
    def __init__(self, sql: str):
        self.sql = sql
        self.tokens = tokenize(sql)
        self.pos = 0

    # -- token helpers -------------------------------------------------

    @property
    def tok(self) -> Token:
        return self.tokens[self.pos]

    def peek(self, offset: int = 1) -> Token:
        return self.tokens[min(self.pos + offset, len(self.tokens) - 1)]

    def advance(self) -> Token:
        tok = self.tokens[self.pos]
        if tok.kind != EOF:
            self.pos += 1
        return tok

    def error(self, message: str, tok: Optional[Token] = None) -> QueryError:
        tok = tok or self.tok
        return _error(self.sql, tok.start, message)

    def unexpected(self, expected: str) -> QueryError:
        tok = self.tok
        if tok.kind == KEYWORD and expected.startswith(("a name", "an expression", "a table")):
            return self.error(
                "expected %s, got keyword %s (keywords can't be used as names;"
                ' quote it as "%s")' % (expected, tok.value, self.sql[tok.start : tok.end])
            )
        return self.error("expected %s, got %s" % (expected, _describe(tok)))

    def is_kw(self, *words: str) -> bool:
        return self.tok.kind == KEYWORD and self.tok.value in words

    def is_op(self, *ops: str) -> bool:
        return self.tok.kind == OP and self.tok.value in ops

    def accept_kw(self, word: str) -> bool:
        if self.is_kw(word):
            self.advance()
            return True
        return False

    def accept_op(self, op: str) -> bool:
        if self.is_op(op):
            self.advance()
            return True
        return False

    def expect_kw(self, word: str) -> Token:
        if not self.is_kw(word):
            raise self.unexpected(word)
        return self.advance()

    def expect_op(self, op: str) -> Token:
        if not self.is_op(op):
            raise self.unexpected("'%s'" % op)
        return self.advance()

    def expect_name(self, what: str = "a name") -> str:
        if self.tok.kind in (NAME, QNAME):
            return self.advance().value
        raise self.unexpected(what)

    # -- query ---------------------------------------------------------

    def parse_query(self) -> ast.Query:
        if self.tok.kind == EOF:
            raise self.error("empty query")
        self.expect_kw("SELECT")
        distinct = self.accept_kw("DISTINCT")
        columns = self.parse_columns()
        self.expect_kw("FROM")
        table = self.expect_name("a table name")
        query = ast.Query(distinct=distinct, columns=columns, table=table)
        if self.accept_kw("WHERE"):
            query.where = self.parse_expr()
        if self.accept_kw("GROUP"):
            self.expect_kw("BY")
            query.group_by = [self.parse_expr()]
            while self.accept_op(","):
                query.group_by.append(self.parse_expr())
        if self.accept_kw("HAVING"):
            query.having = self.parse_expr()
        if self.accept_kw("ORDER"):
            self.expect_kw("BY")
            query.order_by = [self.parse_order_item()]
            while self.accept_op(","):
                query.order_by.append(self.parse_order_item())
        if self.accept_kw("LIMIT"):
            query.limit = self.parse_count("LIMIT")
            if self.accept_kw("OFFSET"):
                query.offset = self.parse_count("OFFSET")
        self.accept_op(";")
        if self.tok.kind != EOF:
            raise self.error("unexpected %s after end of query" % _describe(self.tok))
        return query

    def parse_columns(self) -> Optional[List[ast.SelectColumn]]:
        if self.accept_op("*"):
            if self.is_op(","):
                raise self.error("'*' can't be combined with other columns")
            return None
        columns = [self.parse_column()]
        while self.accept_op(","):
            if self.is_op("*"):
                raise self.error("'*' can't be combined with other columns")
            columns.append(self.parse_column())
        return columns

    def parse_column(self) -> ast.SelectColumn:
        first = self.pos
        expr = self.parse_expr()
        text = self.sql[self.tokens[first].start : self.tokens[self.pos - 1].end]
        alias = None
        if self.accept_kw("AS"):
            alias = self.expect_name("a name after AS")
        elif self.tok.kind in (NAME, QNAME):
            alias = self.advance().value
        return ast.SelectColumn(expr=expr, alias=alias, text=text)

    def parse_order_item(self) -> ast.OrderItem:
        expr = self.parse_expr()
        descending = False
        if self.accept_kw("DESC"):
            descending = True
        else:
            self.accept_kw("ASC")
        return ast.OrderItem(expr=expr, descending=descending)

    def parse_count(self, clause: str) -> int:
        if self.tok.kind != INT:
            raise self.unexpected("a non-negative integer after %s" % clause)
        return self.advance().value

    # -- expressions ---------------------------------------------------

    def parse_expr(self) -> ast.Expr:
        return self.parse_or()

    def parse_or(self) -> ast.Expr:
        left = self.parse_and()
        while self.accept_kw("OR"):
            left = ast.Binary("OR", left, self.parse_and())
        return left

    def parse_and(self) -> ast.Expr:
        left = self.parse_not()
        while self.accept_kw("AND"):
            left = ast.Binary("AND", left, self.parse_not())
        return left

    def parse_not(self) -> ast.Expr:
        if self.accept_kw("NOT"):
            return ast.Unary("NOT", self.parse_not())
        return self.parse_comparison()

    def parse_comparison(self) -> ast.Expr:
        left = self.parse_additive()
        tok = self.tok
        if tok.kind == OP and tok.value in ("=", "!=", "<>", "<", "<=", ">", ">="):
            self.advance()
            op = "!=" if tok.value == "<>" else tok.value
            result = ast.Binary(op, left, self.parse_additive())  # type: ast.Expr
        elif self.accept_kw("IS"):
            negated = self.accept_kw("NOT")
            self.expect_kw("NULL")
            result = ast.IsNull(left, negated)
        elif self.is_kw("NOT") and self.peek().kind == KEYWORD and self.peek().value in ("IN", "BETWEEN", "LIKE"):
            self.advance()
            result = self.parse_predicate(left, negated=True)
        elif self.is_kw("IN", "BETWEEN", "LIKE"):
            result = self.parse_predicate(left, negated=False)
        else:
            return left
        if self.is_comparison_start():
            raise self.error(
                "comparisons can't be chained; use parentheses or AND (got %s)" % _describe(self.tok)
            )
        return result

    def is_comparison_start(self) -> bool:
        if self.is_op("=", "!=", "<>", "<", "<=", ">", ">="):
            return True
        if self.is_kw("IS", "IN", "BETWEEN", "LIKE"):
            return True
        return self.is_kw("NOT") and self.peek().kind == KEYWORD and self.peek().value in ("IN", "BETWEEN", "LIKE")

    def parse_predicate(self, left: ast.Expr, negated: bool) -> ast.Expr:
        word = self.advance().value
        if word == "IN":
            self.expect_op("(")
            items = [self.parse_expr()]
            while self.accept_op(","):
                items.append(self.parse_expr())
            self.expect_op(")")
            return ast.In(left, items, negated)
        if word == "BETWEEN":
            low = self.parse_additive()
            self.expect_kw("AND")
            high = self.parse_additive()
            return ast.Between(left, low, high, negated)
        return ast.Like(left, self.parse_additive(), negated)

    def parse_additive(self) -> ast.Expr:
        left = self.parse_multiplicative()
        while self.is_op("+", "-", "||"):
            op = self.advance().value
            left = ast.Binary(op, left, self.parse_multiplicative())
        return left

    def parse_multiplicative(self) -> ast.Expr:
        left = self.parse_unary()
        while self.is_op("*", "/"):
            op = self.advance().value
            left = ast.Binary(op, left, self.parse_unary())
        return left

    def parse_unary(self) -> ast.Expr:
        if self.accept_op("-"):
            return ast.Unary("-", self.parse_unary())
        return self.parse_primary()

    def parse_primary(self) -> ast.Expr:
        tok = self.tok
        if tok.kind in (INT, FLOAT, STRING):
            self.advance()
            return ast.Literal(tok.value)
        if tok.kind == KEYWORD and tok.value in ("NULL", "TRUE", "FALSE"):
            self.advance()
            return ast.Literal({"NULL": None, "TRUE": True, "FALSE": False}[tok.value])
        if tok.kind == QNAME:
            self.advance()
            return ast.Name(tok.value)
        if tok.kind == NAME:
            self.advance()
            if self.is_op("("):
                return self.parse_call(tok)
            return ast.Name(tok.value)
        if self.accept_op("("):
            expr = self.parse_expr()
            self.expect_op(")")
            return expr
        if tok.kind == OP and tok.value == "*":
            raise self.error("'*' is only allowed as SELECT * or as a function argument like COUNT(*)")
        raise self.unexpected("an expression")

    def parse_call(self, name_tok: Token) -> ast.Call:
        name = name_tok.value.upper()
        self.expect_op("(")
        if self.accept_op("*"):
            self.expect_op(")")
            return ast.Call(name, [], star=True)
        args = []  # type: List[ast.Expr]
        if not self.is_op(")"):
            args.append(self.parse_expr())
            while self.accept_op(","):
                args.append(self.parse_expr())
        self.expect_op(")")
        return ast.Call(name, args)


def parse(sql: str) -> ast.Query:
    """Parse a SELECT query into a :class:`minisql.ast.Query`."""
    if not isinstance(sql, str):
        raise QueryError("query must be a string")
    return _Parser(sql).parse_query()

